import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;
        int cases = 1; // as per original code, only one case
        for (int i = 0; i < cases; i++) {
            execute(br);
        }
    }

    public static void execute(BufferedReader br) throws IOException {
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        double[] p = new double[n];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < n; i++) {
            p[i] = Double.parseDouble(st.nextToken());
        }

        StringBuilder output = new StringBuilder();

        for (int i = 0; i < n; i++) {
            if (Math.abs(p[i]) < 1e-6) {
                output.append("0 ");
                continue;
            }
            int size = n - 1;
            int totalMasks = 1 << size;
            double[] dp = new double[totalMasks];
            Arrays.fill(dp, 0.0);
            List<Double> others = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (j != i) {
                    others.add(p[j]);
                }
            }
            dp[0] = p[i];
            double sum_result = dp[0];

            for (int mask = 1; mask < totalMasks; mask++) {
                double sumP = 0.0;
                double sumVal = 0.0;
                int cnt = 0;
                for (int t = 0; t < size; t++) {
                    if (((mask >> t) & 1) == 1) {
                        sumP += others.get(t);
                        sumVal += others.get(t) * dp[mask ^ (1 << t)];
                        cnt++;
                    }
                }
                double denom = 1 - sumP;
                if (Math.abs(denom) < 1e-12) {
                    // To avoid division by zero, skip or handle accordingly
                    continue;
                }
                dp[mask] = sumVal / denom;
                if (cnt < k) {
                    sum_result += dp[mask];
                }
            }
            output.append(sum_result).append(" ");
        }
        System.out.println(output.toString().trim());
    }
}
